/* Nearby-force candidate: 529 generated bytes versus 532 original; unmatched. */
#pragma pack(push, 1)
typedef struct {
    long x, y, z;
    short cstat, picnum;
    signed char shade;
    unsigned char pal, clipdist, filler, xrepeat, yrepeat;
    signed char xoffset, yoffset;
    short sectnum, statnum, ang, owner, xvel, yvel, zvel, lotag, hitag, extra;
} ForceSprite;
#pragma pack(pop)
extern ForceSprite force_sprites[];
extern short force_headspritestat[], force_nextspritestat[], force_sprite_mapping[];
extern unsigned char force_mapped_state[];
extern long force_player_x, force_player_y;
extern const float force_normalizer, force_numerator, force_cap, force_vertical;
extern long force_abs(long);
extern long force_distance(long);
extern void force_player_effect(long);
extern int force_random(void);
extern void force_sound(long,long,long,long);
extern void force_start_sequence(short);
extern void force_append_movement(short);

void apply_nearby_force(short source)
{
    short sprite, next, mapped;
    long dx, dy, distance, tag, mapping, tile;
    float normalizer, power;
    dx = force_player_x - force_sprites[source].x;
    dy = force_player_y - force_sprites[source].y;
    if (force_abs(dx) < 1024 && force_abs(dy) < 1024) {
        force_player_effect(-400);
        force_sound(15 + force_random() % 2, 0, 0, 0);
    }
    for (sprite = force_headspritestat[0]; sprite >= 0; sprite = next) {
        next = force_nextspritestat[sprite];
        dx = force_sprites[sprite].x - force_sprites[source].x;
        dy = force_sprites[sprite].y - force_sprites[source].y;
        if (force_abs(dx) >= 1024 || force_abs(dy) >= 1024) continue;
        tag = (short)(force_sprites[sprite].lotag & 255);
        if (tag == 100 || tag == 101) {
            distance = force_distance(dx*dx + dy*dy);
            normalizer = force_normalizer / distance;
            power = force_numerator / (distance*distance);
            if (power > force_cap) power = 3.0f;
            force_sprites[sprite].xvel = dx * normalizer * power;
            force_sprites[sprite].yvel = dy * normalizer * power;
            force_sprites[sprite].zvel = force_vertical * power;
            force_start_sequence(sprite);
            mapped = force_sprite_mapping[sprite];
            mapping = mapped;
            if (mapping != -1) {
                force_mapped_state[mapping] = 3;
                force_sprites[sprite].clipdist *= 2;
                force_sprites[sprite].cstat = 0;
            }
            force_append_movement(sprite);
        }
        tile = force_sprites[sprite].picnum;
        if (tile == 340) force_start_sequence(sprite);
    }
}
